<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { ClipboardList, GitBranch, Plus, Search } from 'lucide-vue-next'
import Modal from '../components/Modal.vue'
import Pager from '../components/Pager.vue'
import { all, api, dateLabel, isArchived, messageOf, notify, pickFields, projectName, query, taskStatuses, ui } from '../api'
import type { Page, Task } from '../types'
const props=defineProps<{revision:number;initialProject?:string;initialQuery?:string}>();const emit=defineEmits<{changed:[]}>()
const tasks=ref<Task[]>([]),parentTasks=ref<Task[]>([]),total=ref(0),offset=ref(0),project=ref(props.initialProject||''),status=ref(''),search=ref(props.initialQuery||''),error=ref(''),loading=ref(false),open=ref(false),saving=ref(false),formError=ref(''),editing=ref<Task>();const limit=50
const blank=()=>({project_id:project.value||ui.projects.find(p=>p.status!=='archived')?.id||'',parent_id:'',name:'',assignee:'',plan_start:'',plan_end:'',progress:0,status:'todo',priority:2,estimate_hours:0,description:''});const form=reactive(blank())
const readonly=computed(()=>editing.value?.status==='done'||isArchived(editing.value?.project_id||''))
const derived=computed(()=>!!editing.value&&parentTasks.value.some(t=>t.parent_id===editing.value!.id))
const rows=computed(()=>{const ids=new Set(tasks.value.map(t=>t.id));const result:Array<{task:Task;depth:number}>=[];const seen=new Set<string>();function walk(parent:string,depth:number){for(const task of tasks.value.filter(t=>t.parent_id===parent||(!parent&&!ids.has(t.parent_id)))){if(seen.has(task.id))continue;seen.add(task.id);result.push({task,depth});walk(task.id,depth+1)}}walk('',0);tasks.value.filter(t=>!seen.has(t.id)).forEach(task=>result.push({task,depth:0}));return result})
const parentChoices=computed(()=>{const blocked=new Set<string>();if(editing.value){blocked.add(editing.value.id);let changed=true;while(changed){changed=false;parentTasks.value.forEach(t=>{if(blocked.has(t.parent_id)&&!blocked.has(t.id)){blocked.add(t.id);changed=true}})}}return parentTasks.value.filter(t=>!blocked.has(t.id)&&t.project_id===form.project_id&&(!['done','canceled'].includes(t.status)||t.id===editing.value?.parent_id))})
async function load(){loading.value=true;error.value='';try{const page=await api<Page<Task>>(`/api/tasks?${query({project_id:project.value,status:status.value,q:search.value,offset:offset.value,limit})}`);tasks.value=page.items;total.value=page.total}catch(e){error.value=messageOf(e)}finally{loading.value=false}}
async function loadParents(){if(!form.project_id){parentTasks.value=[];return}try{parentTasks.value=await all<Task>('/api/tasks',{project_id:form.project_id})}catch(e){formError.value=messageOf(e)}}
onMounted(load);watch(()=>props.revision,load);watch([project,status],()=>{offset.value=0;void load()});watch(()=>props.initialProject,(id)=>{project.value=id||''});watch(()=>props.initialQuery,(q)=>{search.value=q||'';offset.value=0;void load()});watch(()=>form.project_id,()=>{form.parent_id='';void loadParents()})
async function edit(task?:Task){editing.value=task;Object.assign(form,task?pickFields(task,blank()):blank());formError.value='';open.value=true;await loadParents();if(task)form.parent_id=task.parent_id}
async function save(){if(saving.value||readonly.value)return;saving.value=true;formError.value='';try{await api(editing.value?`/api/tasks/${editing.value.id}`:'/api/tasks',{method:editing.value?'PATCH':'POST',body:JSON.stringify({...pickFields(form,blank()),progress:Number(form.progress),priority:Number(form.priority),estimate_hours:Number(form.estimate_hours),...(editing.value?{version:editing.value.version}:{})})});open.value=false;notify(editing.value?'任务已更新':'任务已创建');emit('changed');await load()}catch(e){formError.value=messageOf(e)}finally{saving.value=false}}
function page(next:number){offset.value=next;void load()}
</script>
<template><div class="page-heading"><div><h1>任务与 WBS</h1><p class="page-description">把工作逐层拆开，进度和责任落到每一项。</p></div><button class="button primary" :disabled="!ui.projects.some(p=>p.status!=='archived')" @click="edit()"><Plus :size="18"/>新增任务</button></div><form class="filter-bar" @submit.prevent="offset=0;load()"><select v-model="project" aria-label="筛选项目"><option value="">全部项目</option><option v-for="p in ui.projects" :key="p.id" :value="p.id">{{p.name}}{{p.status==='archived'?'（已归档）':''}}</option></select><select v-model="status" aria-label="任务状态"><option value="">全部状态</option><option v-for="(name,key) in taskStatuses" :key="key" :value="key">{{name}}</option></select><div class="input-with-icon"><Search :size="16"/><input v-model="search" placeholder="搜索任务" aria-label="搜索任务"/></div><button type="submit" class="button subtle">查询</button></form><div v-if="error" class="error-banner" role="alert">{{error}}<button class="text-button" @click="load">重试</button></div><div class="surface"><div class="table-caption"><span><GitBranch :size="15"/>WBS 层级视图</span><span class="muted">{{total}} 项任务 · 子任务可在编辑中调整上级</span></div><p v-if="loading" class="loading-message">正在读取任务…</p><div v-else-if="!tasks.length" class="empty-state"><ClipboardList :size="38"/><h2>{{ui.projects.length?'还没有符合条件的任务':'先建立一个项目'}}</h2><p>{{ui.projects.length?'从一个明确的工作项开始，逐步拆成子任务。':'任务需要关联项目。前往「项目」新建项目后再分解工作。'}}</p><button v-if="ui.projects.some(p=>p.status!=='archived')" class="button primary" @click="edit()">新增任务</button></div><div v-else class="table-scroll"><table class="task-table"><thead><tr><th>任务 / 项目</th><th>负责人</th><th>计划结束</th><th>进度</th><th>状态</th><th class="right">操作</th></tr></thead><tbody><tr v-for="{task,depth} in rows" :key="task.id"><td><div class="wbs-title" :style="{paddingLeft:`${depth*20}px`}"><span class="wbs-code">{{task.wbs_code||'—'}}</span><div><button class="table-title" @click="edit(task)">{{task.name}}</button><small v-if="!project">{{projectName(task.project_id)}}</small></div></div></td><td>{{task.assignee||'未指定'}}</td><td :class="{overdue:task.overdue}">{{dateLabel(task.plan_end)}}<small v-if="task.overdue">已逾期</small></td><td><div class="progress-label"><div class="progress-track"><i :style="{width:`${task.progress}%`}"/></div><span>{{task.progress}}%</span></div></td><td><span class="badge" :class="task.status">{{taskStatuses[task.status]}}</span></td><td class="right"><button class="text-button" @click="edit(task)">{{task.status==='done'||isArchived(task.project_id)?'查看':'编辑'}}</button></td></tr></tbody></table></div><Pager :offset="offset" :limit="limit" :total="total" @change="page"/></div><Modal :open="open" :title="readonly?'任务详情':editing?'编辑任务':'新增任务'" wide @close="!saving&&(open=false)"><form class="modal-body" @submit.prevent="save"><fieldset :disabled="readonly||saving"><label>任务名称 <span class="required">*</span><input v-model="form.name" required maxlength="200" autofocus/></label><div class="form-row"><label>所属项目 <span class="required">*</span><select v-model="form.project_id" required :disabled="!!editing"><option v-for="p in ui.projects.filter(p=>p.status!=='archived'||p.id===form.project_id)" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label>上级任务<select v-model="form.parent_id"><option value="">无，作为顶层任务</option><option v-for="task in parentChoices" :key="task.id" :value="task.id">{{task.wbs_code}} {{task.name}}</option></select></label></div><div class="form-row"><label>负责人<input v-model="form.assignee" maxlength="100"/></label><label>优先级<select v-model.number="form.priority"><option :value="1">高</option><option :value="2">中</option><option :value="3">低</option></select></label></div><div class="form-row"><label>计划开始<input v-model="form.plan_start" type="date"/></label><label>计划结束<input v-model="form.plan_end" type="date" :min="form.plan_start||undefined"/></label></div><div class="form-row"><label>任务状态<select v-model="form.status" :disabled="derived"><option v-for="(name,key) in taskStatuses" :key="key" :value="key">{{name}}</option></select></label><label>完成进度 %<input v-model.number="form.progress" :disabled="derived" type="number" min="0" max="100" step="1" required/></label></div><label>预计工时（小时）<input v-model.number="form.estimate_hours" :disabled="derived" type="number" min="0" step="0.5"/></label><label>任务说明<textarea v-model="form.description" rows="3"/></label></fieldset><p v-if="formError" class="form-error" role="alert">{{formError}}</p><div class="modal-footer"><span class="muted">{{readonly?'已完成或已归档的任务只读':form.status==='done'?'保存为已完成后，任务进入只读状态':derived?'父任务状态、进度和工时由子任务汇总':'调整上级任务即可移动层级'}}</span><button v-if="!readonly" type="submit" class="button primary" :disabled="saving">{{saving?'正在保存…':'保存任务'}}</button></div></form></Modal></template>
